const {chromium}=require('playwright');const assert=require('node:assert/strict');
(async()=>{const base=process.env.ALPHA_BASE_URL||'https://tuuvo.app.br';const browser=await chromium.launch({headless:true,executablePath:process.env.CHROME_PATH||'/usr/bin/google-chrome'});try{const page=await browser.newPage({viewport:{width:1280,height:900}});const errors=[];page.on('pageerror',e=>errors.push(e.message));const response=await page.goto(base+'/experience',{waitUntil:'networkidle'});assert.equal(response.status(),200);await page.locator('#select-corporate').click();await page.getByRole('button',{name:/Começar a experiência/}).click();await page.locator('#context').waitFor({state:'visible'});assert.ok(await page.locator('#context').evaluate(e=>e.getBoundingClientRect().bottom<document.querySelector('#media').getBoundingClientRect().top),'Situation must appear before the illustration');await page.getByRole('button',{name:'Reproduzir vídeo com narração',exact:true}).click();await page.waitForFunction(()=>{const v=document.querySelector('video');return v.readyState>=2&&!v.paused&&v.currentTime>1});assert.ok(await page.locator('video').evaluate(v=>v.duration>=24));const audible=await page.locator('video').evaluate(async video=>{const context=new AudioContext();await context.resume();const source=context.createMediaElementSource(video);const analyser=context.createAnalyser();analyser.fftSize=2048;source.connect(analyser);analyser.connect(context.destination);window.__audioProbe=context;const samples=new Float32Array(analyser.fftSize);for(let i=0;i<50;i++){analyser.getFloatTimeDomainData(samples);if(samples.some(v=>Math.abs(v)>.002))return true;await new Promise(r=>setTimeout(r,50))}return false});assert.equal(audible,true,'Video must produce a decoded, non-silent audio signal');await page.route('**/api/demo/step',async route=>{await new Promise(r=>setTimeout(r,350));await route.continue()});await page.setViewportSize({width:390,height:844});await page.locator('#choices button').nth(2).click();assert.equal(await page.locator('#leave').isDisabled(),true);await page.waitForFunction(()=>document.querySelector('#phaseCount').textContent.includes('FASE 2'));assert.match(await page.locator('#phaseNotice').textContent(),/Fase 1 concluída.*fase 2 de 6/);assert.equal(await page.locator('#progress [aria-current=step]').count(),1);assert.equal(await page.evaluate(()=>scrollY),0);assert.equal(await page.locator('#phaseFeedback').isVisible(),true);await page.screenshot({path:'/tmp/alpha-browser/fase-2-mobile.png',fullPage:true});await page.setViewportSize({width:1280,height:900});await page.getByRole('button',{name:'Pausar jornada',exact:true}).click();await page.reload({waitUntil:'networkidle'});await page.locator('#select-corporate').click();await page.getByRole('button',{name:'Retomar meu percurso',exact:true}).click();await page.waitForFunction(()=>document.querySelector('#phaseCount').textContent.includes('FASE 2'));for(let i=1;i<6;i++){await page.locator('#choices button').nth(2).click();if(i<5)await page.waitForFunction(n=>document.querySelector('#phaseCount').textContent.includes('FASE '+n),i+2);else await page.waitForFunction(()=>!document.querySelector('#results').classList.contains('hidden'))}assert.equal(await page.locator('#firstScore').textContent(),'0.0');assert.match(await page.locator('#resultTitle').textContent(),/diagnóstico/);assert.ok((await page.locator('.diagnosis').boundingBox()).y<500);assert.match(await page.locator('#diagnosisNext').textContent(),/Revisite/);await page.setViewportSize({width:390,height:844});assert.ok((await page.locator('#diagnosisTitle').boundingBox()).y<500);await page.screenshot({path:'/tmp/alpha-browser/diagnostico-mobile.png',fullPage:true});await page.setViewportSize({width:1280,height:900});await page.getByRole('button',{name:/Revisitar outros caminhos/}).click();for(let i=0;i<6;i++){await page.locator('#choices button').first().click();if(i<5)await page.waitForFunction(n=>document.querySelector('#phaseCount').textContent.includes('FASE '+n),i+2);else await page.waitForFunction(()=>document.querySelector('#currentScore').textContent==='100.0')}assert.equal(await page.locator('#firstScore').textContent(),'0.0');assert.match(await page.locator('#diagnosisNext').textContent(),/maior pontuação/);await page.waitForFunction(()=>document.querySelector('#comparison').getAttribute('aria-busy')==='false');assert.equal(await page.locator('#comparisonScore').textContent(),'0,0 / 100');assert.match(await page.locator('#comparisonExplanation').textContent(),/pontos abaixo da média/);assert.equal(await page.locator('#participantBar').evaluate(e=>e.style.width),'0%');assert.equal(await page.locator('.phase-row').count(),6);await page.selectOption('#scope','A');await page.waitForFunction(()=>document.querySelector('#cohortText').textContent.includes('12'));const groupMean=await page.evaluate(async()=>{const d=await(await fetch('/api/demo/benchmark?score=0&scope=A')).json();return new Intl.NumberFormat('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1}).format(d.scores.reduce((s,v)=>s+v,0)/d.scores.length)});assert.equal(await page.locator('#comparisonMean').textContent(),groupMean+' / 100');assert.equal(await page.locator('#benchmarkMean').textContent(),groupMean);assert.equal(await page.locator('#comparisonScore').textContent(),'0,0 / 100');const download=page.waitForEvent('download');await page.getByRole('button',{name:'Baixar minha síntese',exact:true}).click();assert.equal((await download).suggestedFilename(),'tuuvo-minha-sintese.txt');await page.screenshot({path:process.env.ALPHA_SCREENSHOT||'/tmp/alpha-browser/alpha-publicada.png',fullPage:true});await page.setViewportSize({width:390,height:844});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await page.locator('#comparison').screenshot({path:'/tmp/alpha-browser/comparacao-mobile.png'});await page.getByRole('button',{name:/Apagar meus percursos/}).click();await page.screenshot({path:process.env.ALPHA_MOBILE_SCREENSHOT||'/tmp/alpha-browser/alpha-mobile.png',fullPage:true});assert.deepEqual(errors,[]);console.log('PASS: clear phase transition, situation before media, visible diagnostic summary, narrated video playback and non-silent audio, six phases, resume, two distinct attempts, benchmark, report download, mobile and no JS errors')}finally{await browser.close()}})().catch(e=>{console.error('::error title=Public journey validation::'+e.message.replace(/\n/g,'%0A').replace(/\r/g,'%0D'));process.exit(1)});
